package com.cowave.search.collection.model

import org.bson.types.ObjectId
import org.springframework.data.annotation.Id
import org.springframework.data.mongodb.core.index.CompoundIndex
import org.springframework.data.mongodb.core.index.Indexed
import org.springframework.data.mongodb.core.mapping.Document

/**
 * 컬렉션 설정 도큐먼트.
 *
 * 기존 ES `.dsearch_collection` 도큐먼트를 MongoDB로 이전.
 * - A/B 인덱스 상태(health, docsCount 등)는 ES 실시간 조회이므로 저장하지 않음
 * - launcher 설정은 YAML 문자열 그대로 저장 (구조가 자유롭고 인덱서에 그대로 전달됨)
 */
@Document(collection = "collections")
@CompoundIndex(def = "{'clusterId': 1, 'baseId': 1}", unique = true)
data class Collection(
    @Id
    val id: String = ObjectId.get().toHexString(),
    @Indexed
    val clusterId: String,
    var name: String,
    var baseId: String,
    var scheduled: Boolean = false,
    var jdbcId: String? = null,
    var cron: String? = null,
    var sourceName: String? = null,
    var autoRun: Boolean = false,
    var replicas: Int? = null,
    var refreshInterval: Int? = null,
    var ignoreRoleYn: String? = null,
    var indexingType: String? = null,
    var extIndexer: Boolean = false,
    // 외부 인덱서 ES 접속 정보 (extIndexer=true 시 사용)
    var esScheme: String? = null,
    var esHost: String? = null,
    var esPort: String? = null,
    var esUser: String? = null,
    var esPassword: String? = null,
    // 외부 인덱서 런처 설정 (YAML 문자열)
    var launcherYaml: String? = null,
    // 런처 접속 정보
    var launcherScheme: String? = null,
    var launcherHost: String? = null,
    var launcherPort: String? = null,
)

package com.cowave.search.collection.model

/**
 * 진행 중인 색인 작업 정보 (메모리 큐).
 *
 * manageQueue(ConcurrentHashMap<collectionId, IndexingInfo>)에 저장되어
 * @Scheduled 폴링(1초)으로 상태를 추적한다.
 */
data class IndexingInfo(
    val collection: Collection,
    val clusterId: String,
    val index: String,
    val scheme: String = "http",
    val host: String = "localhost",
    val port: Int = 8080,
    var indexingJobId: String? = null,
    var status: IndexingStatus = IndexingStatus.RUNNING,
    val startTime: Long = System.currentTimeMillis(),
    var endTime: Long? = null,
    var currentStep: IndexingStep = IndexingStep.FULL_INDEX,
    val nextSteps: ArrayDeque<IndexingStep> = ArrayDeque(),
    var retry: Int = 0,
) {
    val collectionId: String get() = collection.id
}

enum class IndexingStatus {
    RUNNING,
    SUCCESS,
    ERROR,
    STOP,
}

enum class IndexingStep {
    FULL_INDEX,
    DYNAMIC_INDEX,
    EXPOSE,
    REMOVED,
}

package com.cowave.search.common.elasticsearch

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.json.jackson.JacksonJsonpMapper
import co.elastic.clients.transport.rest5_client.Rest5ClientTransport
import co.elastic.clients.transport.rest5_client.low_level.Rest5Client
import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.databind.SerializationFeature
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule
import com.fasterxml.jackson.module.kotlin.kotlinModule
import jakarta.annotation.PreDestroy
import org.apache.hc.core5.http.Header
import org.apache.hc.core5.http.HttpHost
import org.apache.hc.core5.http.message.BasicHeader
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

/**
 * 멀티 클러스터 Elasticsearch 클라이언트 팩토리.
 *
 * - ConcurrentHashMap 기반 클라이언트 캐시
 * - 클러스터 등록/삭제 시 캐시 갱신
 * - Basic 인증 및 ApiKey 인증 지원
 */
@Component
class ElasticsearchClientFactory {
    private val logger = LoggerFactory.getLogger(ElasticsearchClientFactory::class.java)

    private val clientCache = ConcurrentHashMap<String, CachedClusterClient>()

    private val jsonpMapper by lazy {
        val objectMapper =
            ObjectMapper()
                .registerModule(kotlinModule())
                .registerModule(JavaTimeModule())
                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
        JacksonJsonpMapper(objectMapper)
    }

    fun getClient(clusterId: String): ElasticsearchClient =
        clientCache[clusterId]?.esClient
            ?: throw IllegalArgumentException("등록되지 않은 클러스터입니다: $clusterId")

    fun getLowLevelClient(clusterId: String): Rest5Client =
        clientCache[clusterId]?.restClient
            ?: throw IllegalArgumentException("등록되지 않은 클러스터입니다: $clusterId")

    fun registerCluster(info: ClusterConnectionInfo) {
        val cached = buildCachedClient(info)
        clientCache[info.id] = cached
        logger.info("ES 클러스터 등록: {} ({}://{}:{})", info.id, info.scheme, info.host, info.port)
    }

    fun evictCluster(clusterId: String) {
        clientCache.remove(clusterId)?.let {
            runCatching { it.restClient.close() }
                .onFailure { e -> logger.warn("클러스터 클라이언트 종료 실패: $clusterId", e) }
        }
        logger.info("ES 클러스터 제거: {}", clusterId)
    }

    fun registeredClusterIds(): Set<String> = clientCache.keys.toSet()

    @PreDestroy
    fun closeAll() {
        clientCache.values.forEach { runCatching { it.restClient.close() } }
        clientCache.clear()
        logger.info("모든 ES 클러스터 클라이언트 종료 완료")
    }

    private fun buildCachedClient(info: ClusterConnectionInfo): CachedClusterClient {
        val host = HttpHost.create("${info.scheme}://${info.host}:${info.port}")
        val defaultHeaders = buildAuthHeaders(info)

        val restClient =
            Rest5Client
                .builder(host)
                .setDefaultHeaders(defaultHeaders)
                .build()

        val transport = Rest5ClientTransport(restClient, jsonpMapper)
        val esClient = ElasticsearchClient(transport)

        return CachedClusterClient(restClient, esClient)
    }

    private fun buildAuthHeaders(info: ClusterConnectionInfo): Array<Header> =
        when {
            !info.apiKey.isNullOrBlank() -> {
                arrayOf(BasicHeader("Authorization", "ApiKey ${info.apiKey}"))
            }
            !info.username.isNullOrBlank() && !info.password.isNullOrBlank() -> {
                val credentials = Base64.getEncoder().encodeToString("${info.username}:${info.password}".toByteArray())
                arrayOf(BasicHeader("Authorization", "Basic $credentials"))
            }
            else -> emptyArray()
        }

    private data class CachedClusterClient(
        val restClient: Rest5Client,
        val esClient: ElasticsearchClient,
    )

    data class ClusterConnectionInfo(
        val id: String,
        val scheme: String,
        val host: String,
        val port: Int,
        val username: String? = null,
        val password: String? = null,
        val apiKey: String? = null,
    )
}

package com.cowave.search.dictionary.service

import co.elastic.clients.transport.rest5_client.low_level.Request
import co.elastic.clients.transport.rest5_client.low_level.Rest5Client
import com.cowave.search.dictionary.dto.AllTypesCountResponse
import com.cowave.search.dictionary.dto.AllTypesLastModifiedResponse
import com.cowave.search.dictionary.dto.CompileResult
import com.cowave.search.dictionary.dto.CursorPagedResponse
import com.cowave.search.dictionary.dto.SearchColumn
import com.cowave.search.dictionary.dto.SortType
import com.cowave.search.dictionary.dto.TypeCountResponse
import com.cowave.search.dictionary.dto.TypeLastModifiedResponse
import com.cowave.search.dictionary.model.Dictionary
import com.cowave.search.dictionary.model.Type
import com.cowave.search.utils.DictionaryBinaryCompile
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class DictionaryService(
    val dictionaryRepository: DictionaryRepository,
    val dictionaryBinaryCompile: DictionaryBinaryCompile,
    val restClient: Rest5Client,
) {
    private val logger = LoggerFactory.getLogger(DictionaryService::class.java)

    fun search(
        type: Type,
        size: Int,
        searchColumn: SearchColumn = SearchColumn.ALL,
        word: String? = null,
        isMatch: Boolean = false,
        cursor: String? = null,
        sortType: SortType = SortType.UPDATED,
    ): CursorPagedResponse<Dictionary> {
        val searchAfterList = cursor?.split(CURSOR_DELIMITER)
        val result =
            dictionaryRepository.search(
                type = type,
                size = size,
                searchColumn = searchColumn,
                value = word,
                isMatch = isMatch,
                searchAfter = searchAfterList,
                sortType = sortType,
            )

        return CursorPagedResponse(
            items = result.items,
            total = result.total,
            cursor = result.searchAfter?.joinToString(CURSOR_DELIMITER),
            hasNext = result.hasNext,
        )
    }

    fun create(
        keyword: String?,
        type: Type,
        value: String?,
    ) {
        dictionaryRepository.insert(keyword, type, value)
    }

    fun update(
        id: String,
        keyword: String,
        type: Type,
        value: String?,
    ) {
        dictionaryRepository.update(id, keyword, type, value)
    }

    fun delete(id: String) {
        dictionaryRepository.delete(id)
    }

    fun countByType(type: Type): Long = dictionaryRepository.countByType(type)

    fun compile(type: Type): CompileResult {
        val result = compileWithoutReload(type)
        reloadDictionary()
        return result
    }

    fun compileAll(): List<CompileResult> {
        val results: List<CompileResult> = Type.entries.map { compileWithoutReload(it) }
        reloadDictionary()
        return results
    }

    private fun compileWithoutReload(type: Type): CompileResult {
        val dictionaries = dictionaryRepository.findAllByType(type)
        val pairs = dictionaries.map { it.keyword to it.value }
        val outputFile = dictionaryBinaryCompile.compileToConfiguredPath(pairs, type)

        return CompileResult(
            type = type,
            count = dictionaries.size,
            filePath = outputFile.absolutePath,
            fileSize = outputFile.length(),
        )
    }

    private fun reloadDictionary() {
        logger.info("Reloading dictionary in Elasticsearch...")
        val request = Request("POST", "/_analysis-product-name/reload-dict")
        val response = restClient.performRequest(request)
        val statusCode = response.statusCode
        if (statusCode !in 200..299) {
            throw RuntimeException("Failed to reload dictionary: HTTP $statusCode")
        }
        logger.info("Dictionary reload completed successfully")
    }

    fun getLastModifiedByType(type: Type): TypeLastModifiedResponse {
        val (lastModified, count) = dictionaryRepository.findLastModifiedByType(type)
        return TypeLastModifiedResponse(
            type = type,
            lastModified = lastModified,
            count = count,
        )
    }

    fun getAllTypesLastModified(): AllTypesLastModifiedResponse {
        val allTypesData = dictionaryRepository.findLastModifiedForAllTypes()
        val items =
            Type.entries.map { type ->
                val (lastModified, count) = allTypesData[type] ?: Pair(null, 0L)
                TypeLastModifiedResponse(
                    type = type,
                    lastModified = lastModified,
                    count = count,
                )
            }
        return AllTypesLastModifiedResponse(items)
    }

    fun getAllTypesCounts(): AllTypesCountResponse {
        val allTypesCounts = dictionaryRepository.countAllTypes()
        val items =
            Type.entries.map { type ->
                TypeCountResponse(
                    type = type,
                    count = allTypesCounts[type] ?: 0L,
                )
            }
        val totalCount = items.sumOf { it.count }
        return AllTypesCountResponse(items, totalCount)
    }

    companion object {
        private const val CURSOR_DELIMITER = "|"
    }
}

package com.cowave.search.dictionary.controller

import com.cowave.search.dictionary.dto.AllTypesCountResponse
import com.cowave.search.dictionary.dto.AllTypesLastModifiedResponse
import com.cowave.search.dictionary.dto.CompileResult
import com.cowave.search.dictionary.dto.CreateDictionaryRequest
import com.cowave.search.dictionary.dto.CursorPagedResponse
import com.cowave.search.dictionary.dto.SearchColumn
import com.cowave.search.dictionary.dto.SortType
import com.cowave.search.dictionary.dto.TypeCountResponse
import com.cowave.search.dictionary.dto.TypeLastModifiedResponse
import com.cowave.search.dictionary.dto.UpdateDictionaryRequest
import com.cowave.search.dictionary.model.Dictionary
import com.cowave.search.dictionary.model.Type
import com.cowave.search.dictionary.service.DictionaryService
import org.springframework.http.HttpStatus
import org.springframework.web.bind.annotation.DeleteMapping
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.ResponseStatus
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/dictionaries")
class DictionaryController(
    private val dictionaryService: DictionaryService,
) {
    /**
     * 사전 조회/검색 통합 API
     * - word가 없으면 전체 조회
     * - word가 있으면 검색 (searchColumn에 따라 대상 필드 결정)
     */
    @GetMapping("/{type}")
    fun getDictionary(
        @PathVariable type: Type,
        @RequestParam(defaultValue = "20") size: Int,
        @RequestParam(required = false) cursor: String?,
        @RequestParam(defaultValue = "UPDATED") sort: SortType,
        @RequestParam(defaultValue = "ALL") searchColumn: SearchColumn,
        @RequestParam(required = false) word: String?,
        @RequestParam(defaultValue = "false") isMatch: Boolean,
    ): CursorPagedResponse<Dictionary> =
        dictionaryService.search(
            type = type,
            size = size,
            searchColumn = searchColumn,
            word = word,
            isMatch = isMatch,
            cursor = cursor,
            sortType = sort,
        )

    @GetMapping("/{type}/count")
    fun countByType(
        @PathVariable type: Type,
    ): TypeCountResponse = TypeCountResponse(type, dictionaryService.countByType(type))

    @GetMapping("/{type}/last-modified")
    fun getLastModifiedByType(
        @PathVariable type: Type,
    ): TypeLastModifiedResponse = dictionaryService.getLastModifiedByType(type)

    @GetMapping("/last-modified")
    fun getAllTypesLastModified(): AllTypesLastModifiedResponse = dictionaryService.getAllTypesLastModified()

    @GetMapping("/count")
    fun getAllTypesCounts(): AllTypesCountResponse = dictionaryService.getAllTypesCounts()

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun create(
        @RequestBody request: CreateDictionaryRequest,
    ) {
        dictionaryService.create(request.keyword, request.type, request.value)
    }

    @PutMapping("/{id}")
    fun update(
        @PathVariable id: String,
        @RequestBody request: UpdateDictionaryRequest,
    ) {
        dictionaryService.update(id, request.keyword, request.type, request.value)
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun delete(
        @PathVariable id: String,
    ) {
        dictionaryService.delete(id)
    }

    @PostMapping("/compile/{type}")
    fun compile(
        @PathVariable type: Type,
    ): CompileResult = dictionaryService.compile(type)

    @PostMapping("/compile")
    fun compileAll(): List<CompileResult> = dictionaryService.compileAll()
}

